    let (_, foreign_token) = initialize(&mut foreign)?;
    let (cross_seal_denied, _) = snapshot_transfer(
        &mut foreign,
        "POST",
        &foreign_token,
        &mut archive.as_slice(),
    )?;
    assert_eq!(cross_seal_denied.status, 400);
